class BlogContext : DbContext
{
    public DbSet<Blog> Blogs => Set<Blog>();
    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        modelBuilder.Entity<Blog>(entity =>
        {
            // Breaking change #1: EF 9 renamed "Discriminator" to "$type".
            // Existing documents use "Discriminator", so preserve it.
            entity.HasDiscriminator().HasJsonPropertyName("Discriminator");

            // Breaking change #2: EF 9 changed id format from "EntityName|KeyValue" to just "KeyValue".
            // Existing documents use "Blog|1" format, so opt back in.
            entity.HasPartitionKey(b => b.Id);
            entity.Property(b => b.Id)
                  .HasJsonPropertyName("id");
        });

        // Breaking change #3: EF 9 uses hierarchical partition keys and changes
        // the default id format. Preserve the legacy "Discriminator|Key" id generation.
        modelBuilder.Entity<Blog>()
            .Property<string>("__id")
            .HasJsonPropertyName("id")
            .HasValueGenerator<LegacyIdValueGenerator>();

        // Breaking change #4: Cosmos DB provider no longer supports HasIndex().
        // Indexes in Cosmos are managed via indexing policy, not EF model config.
        // Removed: entity.HasIndex(b => b.Name);
    }
}
